public enum OrderStatus { Created, Paid, Shipped, Cancelled, Completed }

public interface IOrderStateMachine
{
    OrderStatus Status { get; }
    bool TryTransition(OrderStatus target);
}

public sealed class OrderStateMachine : IOrderStateMachine
{
    private static readonly Dictionary<OrderStatus, HashSet<OrderStatus>> Allowed = new()
    {
        [OrderStatus.Created] = [OrderStatus.Paid, OrderStatus.Cancelled],
        [OrderStatus.Paid] = [OrderStatus.Shipped, OrderStatus.Cancelled],
        [OrderStatus.Shipped] = [OrderStatus.Completed],
        [OrderStatus.Cancelled] = [],
        [OrderStatus.Completed] = [],
    };

    private readonly object _sync = new();
    private OrderStatus _status = OrderStatus.Created;

    public OrderStatus Status { get { lock (_sync) return _status; } }

    public bool TryTransition(OrderStatus target)
    {
        lock (_sync)
        {
            if (!Allowed[_status].Contains(target)) return false;
            _status = target;
            return true;
        }
    }
}
